const compactSpatialPromptSection = (value: string, maxChars: number): string => {
    const text = String(value || "").trim();
    if (text.length <= maxChars) return text;
    if (maxChars <= 12) return text.slice(0, Math.max(0, maxChars));
    const marker = "\n…\n";
    const available = maxChars - marker.length;
    const headLength = Math.ceil(available * 0.68);
    const tailLength = available - headLength;
    return `${text.slice(0, headLength).trimEnd()}${marker}${text.slice(-tailLength).trimStart()}`;
};

const composeSpatialVideoPrompt = (
    scenePrompt: string,
    movementGuidance: string,
    maxChars?: number,
): string => {
    const separator = "\n\n";
    const combined = [scenePrompt, movementGuidance].filter(Boolean).join(separator).trim();
    if (!maxChars || combined.length <= maxChars) return combined;

    const available = maxChars - separator.length;
    let sceneBudget = Math.min(scenePrompt.length, Math.floor(available * 0.62));
    let guidanceBudget = available - sceneBudget;
    if (movementGuidance.length < guidanceBudget) {
        guidanceBudget = movementGuidance.length;
        sceneBudget = available - guidanceBudget;
    }
    return [
        compactSpatialPromptSection(scenePrompt, sceneBudget),
        compactSpatialPromptSection(movementGuidance, guidanceBudget),
    ].filter(Boolean).join(separator).slice(0, maxChars);
};

