const fetchVideoBlobWithRetry = async (
    url: string,
    attempts: number,
    timeoutMs = 120_000,
): Promise<Blob> => {
    let lastError: unknown = null;
    for (let attempt = 1; attempt <= attempts; attempt += 1) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
        try {
            const response = await fetch(url, { signal: controller.signal });
            if (!response.ok) throw new Error(`Failed to download generated video (${response.status})`);
            return await response.blob();
        } catch (error) {
            lastError = error;
            console.warn(`[SpatialVideo][download-retry] attempt=${attempt}/${attempts}`, error);
            if (attempt < attempts) {
                await new Promise((resolve) => setTimeout(resolve, attempt * 500));
            }
        } finally {
            clearTimeout(timeoutId);
        }
    }
    throw lastError instanceof Error ? lastError : new Error("Failed to download generated video.");
};

