const normalizeMuiColor = (value: unknown, fallback: string) => {
    const trimmed = String(value || "").trim();
    if (/^[0-9a-f]{3,8}$/i.test(trimmed)) return `#${trimmed}`;
    if (/^#[0-9a-f]{3,8}$/i.test(trimmed)) return trimmed;
    if (/^(rgb|rgba|hsl|hsla)\(/i.test(trimmed)) return trimmed;
    return fallback;
};

const CustomVideoPlayer = React.forwardRef<CustomVideoPlayerHandle, any>(({
    src,
    isZoomPreview,
    matchMobile,
    togglePreviewMode,
    style,
    isActive,
    showDirectLipSync = false,
    isDirectLipSyncGenerating = false,
    onDirectLipSync,
}: any, ref) => {
    const customPlayerDarkMode = useSelector((state: RootState) => state.settings.darkMode);
    const customPlayerAppColorDark = normalizeMuiColor(
        useSelector((state: RootState) => state.settings.appColorDark),
        "#E8BAFA",
    );
    const customPlayerAppColorLight = normalizeMuiColor(
        useSelector((state: RootState) => state.settings.appColorLight),
        "#0099cc",
    );
    const appColor = (customPlayerDarkMode ? customPlayerAppColorDark : customPlayerAppColorLight)
        || (customPlayerDarkMode ? "#E8BAFA" : "#0099cc");
    const videoRef = React.useRef<HTMLVideoElement>(null);
    const playbackDispatch = useDispatch();
    const preferredMuted = useSelector((state: RootState) => state.settings.fullscreenMute);
    const preferredVolume = useSelector((state: RootState) => state.settings.playbackVolume ?? 1);
    const mutedBeforeSnippetRef = React.useRef<boolean | null>(null);
    const [isPlaying, setIsPlaying] = React.useState(true);
    const [progress, setProgress] = React.useState(0);
    const [isMuted, setIsMuted] = React.useState(preferredMuted);
    React.useEffect(() => {
        if (mutedBeforeSnippetRef.current !== null) return;
        setIsMuted(preferredMuted);
        if (videoRef.current) { videoRef.current.muted = preferredMuted; videoRef.current.volume = preferredVolume; }
    }, [preferredMuted, preferredVolume]);
    const [isHovered, setIsHovered] = React.useState(false);
    const [isManualPlay, setIsManualPlay] = React.useState(false);
    const [showHint, setShowHint] = React.useState(false);
    const hintTimeoutRef = React.useRef<any>(null);

    React.useEffect(() => {
        if (videoRef.current) {
            if (isActive) {
                setIsManualPlay(false);
                setShowHint(false);
                if (hintTimeoutRef.current) clearTimeout(hintTimeoutRef.current);
                videoRef.current.currentTime = 0;
                videoRef.current.play().catch(e => console.log("Autoplay blocked", e));
                setIsPlaying(true);
            } else {
                videoRef.current.pause();
                setIsPlaying(false);
            }
        }
    }, [src, isActive]);

    const handleTimeUpdate = () => {
        if (videoRef.current) {
            const current = videoRef.current.currentTime;
            const duration = videoRef.current.duration;
            if (duration > 0) {
                setProgress((current / duration) * 100);
            }
        }
    };

    const handleSeek = (e: any) => {
        const newValue = parseFloat(e.target.value);
        if (videoRef.current) {
            videoRef.current.currentTime = (newValue / 100) * videoRef.current.duration;
            setProgress(newValue);
        }
    };

    const togglePlay = (e: any) => {
        e.stopPropagation();
        if (hintTimeoutRef.current) clearTimeout(hintTimeoutRef.current);
        setShowHint(false);
        if (videoRef.current) {
            if (isPlaying) {
                videoRef.current.pause();
                setIsPlaying(false);
            } else {
                setIsManualPlay(true);
                if (videoRef.current.currentTime >= videoRef.current.duration) {
                    videoRef.current.currentTime = 0;
                }
                videoRef.current.play();
                setIsPlaying(true);
            }
        }
    };

    const toggleMute = (e: any) => {
        e.stopPropagation();
        if (videoRef.current) {
            videoRef.current.muted = !videoRef.current.muted;
            setIsMuted(videoRef.current.muted);
            playbackDispatch(setPlaybackMuted(videoRef.current.muted));
        }
    };

    const handleEnded = () => {
        if (isManualPlay && videoRef.current) {
            videoRef.current.currentTime = 0;
            videoRef.current.play();
        } else {
            setIsPlaying(false);
            setShowHint(true);
            if (hintTimeoutRef.current) clearTimeout(hintTimeoutRef.current);
            hintTimeoutRef.current = setTimeout(() => setShowHint(false), 3000);
        }
    };

    const startSnippetPlayback = React.useCallback(() => {
        const video = videoRef.current;
        if (!video) return;

        if (mutedBeforeSnippetRef.current === null) {
            mutedBeforeSnippetRef.current = video.muted;
        }

        video.pause();
        video.muted = true;
        setIsMuted(true);
        setIsManualPlay(false);
        setShowHint(false);

        const restart = () => {
            video.currentTime = 0;
            video.play()
                .then(() => setIsPlaying(true))
                .catch((error) => {
                    console.warn("Could not play the synced video preview:", error?.message || error);
                    setIsPlaying(false);
                });
        };

        if (video.readyState >= HTMLMediaElement.HAVE_METADATA) {
            restart();
        } else {
            video.addEventListener("loadedmetadata", restart, { once: true });
        }
    }, []);

    const stopSnippetPlayback = React.useCallback(() => {
        const video = videoRef.current;
        if (!video) return;

        video.pause();
        setIsPlaying(false);

        if (mutedBeforeSnippetRef.current !== null) {
            mutedBeforeSnippetRef.current = null;
            video.muted = preferredMuted;
            video.volume = preferredVolume;
            setIsMuted(preferredMuted);
        }
    }, [preferredMuted, preferredVolume]);

    React.useImperativeHandle(ref, () => ({ startSnippetPlayback, stopSnippetPlayback }), [startSnippetPlayback, stopSnippetPlayback]);

    // Calculate visibility
    const isVisible = showHint || (isHovered && !matchMobile) || (!isPlaying && matchMobile);

    return (
        <Box
            sx={{ position: 'relative', width: '100%', height: isZoomPreview ? (matchMobile ? "100dvh" : "100vh") : "100%" }}
            onClick={togglePreviewMode}
            onDoubleClick={togglePreviewMode}
        >
            <video
                ref={videoRef}
                src={src}
                style={style}
                playsInline
                muted={isMuted}
                onTimeUpdate={handleTimeUpdate}
                onEnded={handleEnded}
                onVolumeChange={() => {
                    if (!videoRef.current || mutedBeforeSnippetRef.current !== null) return;
                    playbackDispatch(setPlaybackMuted(videoRef.current.muted));
                    playbackDispatch(setPlaybackVolume(videoRef.current.volume));
                }}
            />
            {showDirectLipSync && (
                <IconButton
                    aria-label="Generate direct lip-sync video"
                    title="Lip Sync Pro"
                    onClick={(event) => {
                        event.preventDefault();
                        event.stopPropagation();
                        onDirectLipSync?.();
                    }}
                    sx={{
                        position: "absolute",
                        top: matchMobile ? 10 : 14,
                        left: "50%",
                        transform: "translateX(-50%)",
                        zIndex: 14,
                        color: isDirectLipSyncGenerating ? (customPlayerDarkMode ? "#000" : "#fff") : "#fff",
                        border: "1px solid rgba(255,255,255,0.34)",
                        backdropFilter: "blur(10px)",
                        background: isDirectLipSyncGenerating ? appColor : "rgba(0,0,0,0.58)",
                        boxShadow: isDirectLipSyncGenerating ? `0 0 0 3px ${alpha(appColor, 0.35)}, 0 0 24px ${alpha(appColor, 0.9)}` : "none",
                        animation: isDirectLipSyncGenerating ? "lipSyncPulse 1s ease-in-out infinite" : "none",
                        "@keyframes lipSyncPulse": {
                            "0%, 100%": { transform: "translateX(-50%) scale(1)", opacity: 1 },
                            "50%": { transform: "translateX(-50%) scale(1.14)", opacity: 0.58 },
                        },
                        "&:hover": { background: "rgba(0,0,0,0.8)" },
                    }}
                >
                    <RecordVoiceOver />
                </IconButton>
            )}

            {/* Play/Pause Button Area - Top 30% */}
            <Box
                {...(isActive ? cb('workstation_video', 'toggle_video_playback', isPlaying ? 'Pause scene video preview' : 'Play scene video preview', 'togglePlay') : {})}
                onClick={togglePlay}
                onMouseEnter={() => !matchMobile && setIsHovered(true)}
                onMouseLeave={() => !matchMobile && setIsHovered(false)}
                sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '30%',
                    display: matchMobile && !isZoomPreview ? 'none' : 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    bgcolor: isVisible ? 'rgba(0,0,0,0.3)' : 'transparent',
                    backdropFilter: isVisible ? 'blur(4px)' : 'none',
                    opacity: isVisible ? 1 : 0,
                    transition: 'all 0.3s ease',
                    cursor: 'pointer',
                    zIndex: 10,
                    pointerEvents: matchMobile && !isZoomPreview ? 'none' : 'auto',
                }}
            >
                <IconButton sx={{ color: 'white' }}>
                    {isPlaying ? <PauseIcon sx={{ fontSize: 60 }} /> : <PlayArrowIcon sx={{ fontSize: 60 }} />}
                </IconButton>
            </Box>

            {/* Glass Seeker Area - Bottom middle */}
            <Box
                onClick={(e) => e.stopPropagation()}
                sx={{
                    position: 'absolute',
                    bottom: 20,
                    left: '50%',
                    transform: 'translateX(-50%)',
                    width: matchMobile ? '50%' : '40%',
                    height: 40,
                    bgcolor: 'rgba(255,255,255,0.1)',
                    backdropFilter: 'blur(10px)',
                    borderRadius: 4,
                    display: 'flex',
                    alignItems: 'center',
                    px: 2,
                    zIndex: 10,
                    border: '1px solid rgba(255,255,255,0.2)',
                }}
            >
                <Box sx={{ width: matchMobile ? '80%' : '90%', pr: 1, display: 'flex', alignItems: 'center' }}>
                    <input
                        type="range"
                        min="0"
                        max="100"
                        value={progress}
                        onChange={handleSeek}
                        style={{
                            width: '100%',
                            cursor: 'pointer',
                            accentColor: 'white'
                        }}
                    />
                </Box>
                <Box sx={{ width: matchMobile ? '20%' : '10%', display: 'flex', justifyContent: 'center' }}>
                    <IconButton
                        {...(isActive ? cb('workstation_video', 'toggle_video_mute', isMuted ? 'Unmute scene video preview' : 'Mute scene video preview', 'toggleMute') : {})}
                        onClick={toggleMute}
                        sx={{ color: 'white', p: 0 }}
                    >
                        {isMuted ? <VolumeOffIcon fontSize="small" /> : <VolumeUpIcon fontSize="small" />}
                    </IconButton>
                </Box>
            </Box>
        </Box>
    );
});

