const DRAW_REF_NAME = "Draw1";
const DRAW_REF_INSTRUCTION = "Follow Camera Direction and Motion from @Draw1.";
const DRAW_REF_INSTRUCTION_REGEX = /\s*Follow\s+Camera\s+Direction\s+and\s+Motion\s+from\s+@Draw1\.?\s*/gi;
const DRAW_REF_REGEX = /(^|[^A-Za-z0-9_])@?Draw1\b/i;

const promptHasDrawReference = (promptValue: any) => DRAW_REF_REGEX.test(String(promptValue || ""));

const ensureDrawReferenceInstruction = (promptValue: any) => {
    const promptText = String(promptValue || "")
        .replace(DRAW_REF_INSTRUCTION_REGEX, "\n")
        .replace(/[ \t]+\n/g, "\n")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
    return insertInstructionIntoCameraSection(promptText, DRAW_REF_INSTRUCTION);
};
const isDrawReferenceSourceSelected = (drawFrame: any) => {
    if (!drawFrame) return false;
    return (drawFrame.selectedSource === "drawn" && !!drawFrame.drawnImageUrl) ||
        (drawFrame.selectedSource === "ai" && !!drawFrame.aiImageUrl);
};

const getDrawReferenceUrl = (drawFrame: any, selectedOnly = false) => {
    if (!drawFrame) return "";
    if (drawFrame.selectedSource === "ai" && drawFrame.aiImageUrl) return drawFrame.aiImageUrl;
    if (drawFrame.selectedSource === "drawn" && drawFrame.drawnImageUrl) return drawFrame.drawnImageUrl;
    if (selectedOnly) return "";
    return drawFrame.aiImageUrl || drawFrame.drawnImageUrl || "";
};

const buildDrawReference = (drawFrame: any) => {
    const imageUrl = getDrawReferenceUrl(drawFrame);
    if (!imageUrl) return null;
    return {
        name: DRAW_REF_NAME,
        url: imageUrl,
        imageUrl,
        image: imageUrl,
        description: drawFrame?.note || "Camera direction and motion reference",
        isMotion: false,
        isDraw: true,
    };
};
const getPromptReferenceUrl = (ref: any): string => {
    return String(ref?.imageUrl || ref?.url || ref?.image || ref?.vipSourceImageUrl || "").trim();
};

const escapePromptReferenceRegExp = (value: string): string => {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
};

const promptMatchesReference = (promptValue: any, ref: any): boolean => {
    const promptText = String(promptValue || "");
    const rawName = String(ref?.name || "").trim();

    if (!promptText || !rawName) {
        return false;
    }

    const compactHandle = `@${rawName.replace(/[^A-Za-z0-9_]/g, "")}`;
    const nameParts = rawName.split(/[\s\-]+/).filter(Boolean);
    const flexibleName = nameParts.length > 0
        ? nameParts.map((part) => escapePromptReferenceRegExp(part)).join("[\\s\\-]*")
        : escapePromptReferenceRegExp(rawName);
    const compactHandlePattern = `${escapePromptReferenceRegExp(compactHandle)}(?![A-Za-z0-9_])`;
    const flexibleHandlePattern = `@\\b${flexibleName}\\b`;
    const matcher = new RegExp(`(${compactHandlePattern}|${flexibleHandlePattern})`, "i");

    return matcher.test(promptText);
};

const dedupePromptReferences = (refs: any[]): any[] => {
    const seen = new Set<string>();

    return refs.filter((ref) => {
        const name = String(ref?.name || "").trim().toLowerCase();
        const url = getPromptReferenceUrl(ref).toLowerCase();
        const key = `${name}|${url}`;

        if (!name && !url) {
            return false;
        }

        if (seen.has(key)) {
            return false;
        }

        seen.add(key);
        return true;
    });
};

