/** Save the existing post projection and complete draft in one revisioned write.
 * A missing migration can use the legacy route; a conflict/closed owner cannot. */
export async function persistEditorDraftMedia(
    controller: DraftController | undefined,
    postId: unknown,
    kind: 'video' | 'image-edit',
    values: Record<string, unknown>,
    legacy: () => any,
): Promise<{ data: any; status?: number }> {
    if (!controller) return Promise.resolve(legacy());
    const owner = controller.getState();
    if (owner.closed || owner.conflicted || owner.hydrating) {
        throw new Error('This creation is not ready to save media.');
    }
    // A frontend connected to an unmigrated backend still has its local owner,
    // but no cloud draft ID. Existing post saves remain available in that case.
    if (!owner.postId) return Promise.resolve(legacy());
    if (Number(postId) !== owner.postId) throw new Error('The media belongs to another creation.');
    // The accepted durable result belongs in the same frozen snapshot as its
    // legacy post projection, even before React commits the parent setters.
    const nativeIndex = Number(values.type);
    if (Number.isInteger(nativeIndex) && nativeIndex >= 0) {
        if (kind === 'video' && typeof values.vid === 'string' && !values.upscale) {
            const section = controller.section<Record<string, any>>('storybook') || {};
            const clips = [...(section.VideoArrayCloud || [])]; clips[nativeIndex] = values.vid;
            const videos = [...(section.VideoArray || [])]; videos[nativeIndex] = values.vid;
            controller.capture('storybook', { VideoArrayCloud: clips, VideoArray: videos });
        }
        if (kind === 'image-edit' && typeof values.img === 'string') {
            const section = controller.section<Record<string, any>>('prompt') || {};
            const images = [...(section.ImagesHdCloud || [])]; images[nativeIndex] = values.img;
            controller.capture('prompt', { ImagesHdCloud: images });
        }
    }
    try {
        return { data: await controller.checkpoint('quiet', { kind, values }), status: 200 };
    } catch (error: any) {
        if (error?.status === 503 && error?.code === 'DRAFTS_NOT_INSTALLED') return Promise.resolve(legacy());
        throw error;
    }
}

