    // Also used by the separate scene-video upload control.
    const readVideoDuration = useCallback((objectUrl: string): Promise<number> => {
        return new Promise((resolve, reject) => {
            const video = document.createElement("video");
            video.preload = "metadata";
            const cleanup = () => {
                window.clearTimeout(timeout);
                video.onloadedmetadata = null; video.onerror = null;
                video.removeAttribute("src"); video.load();
            };
            const timeout = window.setTimeout(() => { cleanup(); reject(new Error("Video metadata timed out.")); }, 15000);
            video.onloadedmetadata = () => { const duration = video.duration || 0; cleanup(); resolve(duration); };
            video.onerror = () => { cleanup(); reject(new Error("Could not read video metadata.")); };
            video.src = objectUrl;
        });
    }, []);

    const readReferenceVideoMetadata = useCallback((objectUrl: string): Promise<{ duration: number }> => {
        return new Promise((resolve, reject) => {
            const video = document.createElement("video");
            const cleanup = () => {
                window.clearTimeout(timeout);
                video.onloadedmetadata = null;
                video.onerror = null;
                video.removeAttribute("src");
                video.load();
            };
            const timeout = window.setTimeout(() => {
                cleanup();
                reject(new Error("Could not read video metadata. Choose another file."));
            }, 15000);
            video.preload = "metadata";
            video.onloadedmetadata = () => {
                const duration = video.duration;
                const valid = Number.isFinite(duration) && duration >= 2 && video.videoWidth >= 2 && video.videoHeight >= 2;
                cleanup();
                if (valid) resolve({ duration });
                else reject(new Error("Choose a readable video at least 2 seconds long."));
            };
            video.onerror = () => {
                cleanup();
                reject(new Error("Could not read this video. Choose another file."));
            };
            video.src = objectUrl;
        });
    }, []);

    // Lightweight S3 upload for a reference video blob: signed URL -> PUT -> clean URL.
    const uploadReferenceVideoToS3 = useCallback(async (file: File): Promise<string> => {
        const response = await axios.post<any>(
            `${CLIK_URL}/get_signed_url_video`,
            { values: { count: 1 } },
            { withCredentials: true }
        );
        const holder = response.data?.holder;
        if (!holder || holder.length !== 1) {
            throw new Error("Invalid signed URL response.");
        }
        const signedUrl = holder[0];
        const { urlVideo } = signedUrl || {};
        if (!urlVideo) throw new Error("No signed URL returned from server.");

        const uploadResponse = await axios.put(urlVideo, file, {
            headers: {
                "Content-Type": file.type || "video/mp4",
                "Cache-Control": IMMUTABLE_VIDEO_CACHE_CONTROL,
            },
        });
        if (uploadResponse.status !== 200 && uploadResponse.status !== 204) {
            throw new Error(`Video upload failed with status ${uploadResponse.status}`);
        }
        return urlVideo.split("?")[0];
    }, [CLIK_URL]);

    const [motionPlanningTier, setMotionPlanningTier] = usePersistedCreationState<PlanningTier>(creationDraft, 'editor', 'motionPlanningTier', 'luna');
