    const handleReferenceVideoFile = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
        const generationTarget = captureSceneTarget(index);
        const safeIndex = resolveSceneTargetIndex(generationTarget);
        if (safeIndex < 0) return;
        const file = event.target.files?.[0];
        // Reset the input so picking the same file again still fires onChange.
        if (event.target) event.target.value = "";
        if (!file) return;
        if (isRefVideoUploading || pendingReferenceVideoRef.current) return;

        if (!file.type.startsWith("video/")) {
            globalErrorEmitter.emit("Please choose a video file.", safeIndex);
            return;
        }
        if (file.size > REF_VIDEO_MAX_BYTES) {
            globalErrorEmitter.emit("Video is too large (max 100MB).", safeIndex);
            return;
        }

        const selectedDuration = Number(time);
        if (!Number.isFinite(selectedDuration) || selectedDuration < 2) {
            globalErrorEmitter.emit("Choose a generation duration of at least 2 seconds before adding a video reference.", safeIndex);
            return;
        }
        // Capture the owner and generation length before upload/transcoding.
        const pending = { file, target: generationTarget, durationCap: Math.min(selectedDuration, REF_VIDEO_MAX_SECONDS) };
        pendingReferenceVideoRef.current = pending;
        setIsRefVideoUploading(true);
        const objectUrl = URL.createObjectURL(file);
        let needsTrim = false;
        try {
            const metadata = await readReferenceVideoMetadata(objectUrl);
            if (pendingReferenceVideoRef.current !== pending) return;
            if (metadata.duration > pending.durationCap + 0.05) {
                needsTrim = true;
                setPendingReferenceVideo(pending);
            } else {
                const uploadedUrl = await uploadReferenceVideoToS3(file);
                handleReferenceVideoUploadSuccess(uploadedUrl);
            }
        } catch (error: any) {
            const completionSceneIndex = resolveSceneTargetIndex(generationTarget);
            if (completionSceneIndex >= 0) {
                globalErrorEmitter.emit(error?.message || "Could not upload reference video.", completionSceneIndex);
            }
        } finally {
            URL.revokeObjectURL(objectUrl);
            if (!needsTrim && pendingReferenceVideoRef.current === pending) pendingReferenceVideoRef.current = null;
            setIsRefVideoUploading(false);
        }
    }, [captureSceneTarget, handleReferenceVideoUploadSuccess, index, isRefVideoUploading, readReferenceVideoMetadata, resolveSceneTargetIndex, time, uploadReferenceVideoToS3]);

