    /**
     * SECURITY-SYNC: The 10-second maximum is enforced independently by
     * server/src/sourceMediaDuration.ts (SOURCE_MEDIA_MAX_SECONDS). If these
     * creation durations are increased, that backend constant must be reviewed
     * and changed too or source-media generation will correctly reject them.
     * Never replace the backend measurement with a client-supplied duration.
     */
    const SHORT_LONG = {
        Mini: { short: 5, long: 10 },
        Pro: { short: 5, long: 10 },
        Prox: { short: 5, long: 10 },
        Proxx: { short: 5, long: 10 },
        Proxxx: { short: 5, long: 10 },
        FalH3: { short: 5, long: 10 },
        pPro: { short: 5, long: 10 },
        Minix: { short: 5, long: 10 },
        _def: { short: 5, long: 10 },
    } as const;

    const getPair = (model: string) =>
        model === "Mini" ? SHORT_LONG.Mini
            : model === "Pro" ? SHORT_LONG.Pro
                : model === "Prox" ? SHORT_LONG.Prox
                    : model === "Proxx" ? SHORT_LONG.Proxx
                        : model === "Proxxx" ? SHORT_LONG.Proxxx
                        : model === "FalH3" ? SHORT_LONG.FalH3
                            : model === "pPro" ? SHORT_LONG.pPro
                                : model === "Minix" ? SHORT_LONG.Minix
                                    : SHORT_LONG._def;

    const isLong = (v: number) => v === 8 || v === 10;

    const isUsableVideoEntry = (value: any) => {
        if (!value) return false;
        if (typeof Blob !== "undefined" && value instanceof Blob) return value.size > 0;
        if (typeof value !== "string") return true;

        const trimmed = value.trim();
        return (
            trimmed !== "" &&
            trimmed !== "EMPTY" &&
            trimmed !== "EMPTY_BSHOT" &&
            trimmed !== "undefined" &&
            trimmed !== "null"
        );
    };

