    const createLipSyncInstruction = useCallback(async (audioUrl: string): Promise<string> => {
        const safeIndex = safeLipSyncIndex;
        const cleanAudioUrl = String(audioUrl || "").trim();
        if (!cleanAudioUrl) {
            throw new Error("Create lip-sync audio before analyzing lyrics.");
        }

        const start = Number(currentMusicSnippet.start);
        const end = Number(currentMusicSnippet.end);
        setLipSyncInstructionStatusAt(safeIndex, "transcribing");

        try {
            const response = await axios.post<any>(
                `${CLIK_URL}/GptLipSyncAudioInstructions`,
                {
                    audioUrl: cleanAudioUrl,
                    start,
                    end,
                    duration: Math.max(0, end - start),
                    sceneIndex: safeIndex,
                },
                { withCredentials: true, timeout: 180000 }
            );

            const instruction = String(response.data?.instruction || "").trim();
            if (!instruction) {
                throw new Error("The audio analysis did not return timing instructions.");
            }

            const transcript = String(response.data?.transcript || "").trim();
            setLipSyncInstructionAt(safeIndex, instruction);
            setLipSyncInstructionMetaAt(safeIndex, (current) => ({
                ...(current || {}),
                audioUrl: cleanAudioUrl,
                sourceMusicUrl: musicModeUrl,
                sourceStart: start,
                sourceEnd: end,
                instruction,
                transcript,
                updatedAt: Date.now(),
            }));

            return instruction;
        } catch (error: any) {
            console.error("Lipsync audio analysis failed:", error);
            setLipSyncInstructionStatusAt(safeIndex, "failed");
            throw error;
        }
    }, [CLIK_URL, currentMusicSnippet, musicModeUrl, safeLipSyncIndex, setLipSyncInstructionAt, setLipSyncInstructionMetaAt, setLipSyncInstructionStatusAt]);

    const applyLipSyncInstructionToPrompt = useCallback(async (instruction: string) => {
        const safeIndex = safeLipSyncIndex;
        // Capture the scene identity ONCE, here, and carry it through. Lip sync
        // is slow (trim → transcribe → apply), so a bare index resolved later
        // can point at a different scene by the time the prompt is committed —
        // which wrote one scene's prompt over another's.
        const lipSyncTarget = captureSceneTarget(safeIndex);
        const basePromptFromArray = Array.isArray(TextVideo) ? TextVideo[safeIndex] : "";
        const basePrompt = String(basePromptFromArray || videotxt || "").trim();
        const cleanInstruction = String(instruction || "").trim();

        if (!basePrompt) {
            throw new Error("Wait for the video prompt to finish before using lip sync.");
        }
        if (!cleanInstruction) {
            throw new Error("No lip-sync timing instruction is available for this scene.");
        }

        const editInstruction = [
            "Use this as lip-sync audio and lyric timing instructions for this scene.",
            "Merge it into the existing video prompt as the character mouth and singing timing reference.",
            "Do not duplicate existing lip-sync, lyric, or audio timing instructions if they are already present; update or replace them.",
            "Keep the existing visual direction, camera, style, character identity, scene action, duration, and model constraints.",
            `Lip-sync timing data: ${cleanInstruction}`,
        ].join(" ");

        settextVidUpdate(editInstruction);
        setLipSyncInstructionStatusAt(safeIndex, "applying");
        const updatedPrompt = await EditGeneratedVisualTextOnlyFn(lipSyncTarget, editInstruction, basePrompt, 1);

        if (!updatedPrompt) {
            throw new Error("Could not apply the lip-sync timing to the video prompt.");
        }

        setLipSyncInstructionMetaAt(safeIndex, (current) => ({
            ...(current || {}),
            instruction: cleanInstruction,
            appliedAt: Date.now(),
        }));
        setLipSyncInstructionStatusAt(safeIndex, "ready");
        return updatedPrompt;
    }, [EditGeneratedVisualTextOnlyFn, TextVideo, captureSceneTarget, safeLipSyncIndex, setLipSyncInstructionMetaAt, setLipSyncInstructionStatusAt, settextVidUpdate, videotxt]);

