    // 2) Upload video to S3 using the signed URL
    const PutVideoInS3WithURL = useCallback(
        async (videoBlob: Blob, signedUrl: string, i: number, videoObjectUrl: any, bShotSaveContextOverride?: BShotSaveContextSnapshot, sceneTargetOverride?: SceneTarget, isCurrentUpload: () => boolean = () => true, expectedPreview?: any, replacedBlob?: Blob, ownsHistory?: () => boolean) => {
            const sceneTarget = sceneTargetOverride || captureSceneTarget(i);
            try {
                console.log("ðŸ”¥ [3] PutVideoInS3WithURL Entry:", {
                    index: i,
                    signedUrl,
                    videoObjectUrl,
                    isBShotModeActive
                });

                console.log("[VIDEO SAVE][2 S3 UPLOAD STARTING]", {
                    sceneTarget,
                    signedUrlWithoutQuery: signedUrl.split("?")[0],
                    blobSize: videoBlob.size,
                    blobType: videoBlob.type,
                    postId: PostId,
                    mode: pageType
                });

                const uploadResponse = await axios.put(signedUrl, videoBlob, {
                    headers: {
                        "Content-Type": videoBlob.type || "video/mp4",
                        "Cache-Control": IMMUTABLE_VIDEO_CACHE_CONTROL,
                    },
                });

                if (uploadResponse.status !== 200 && uploadResponse.status !== 204) {
                    throw new Error(`Video upload failed with status ${uploadResponse.status}`);
                }

                console.log("Video uploaded successfully to S3.");


                // The final S3 link is the signedUrl minus the query parameters del
                const uploadedVideoUrl = signedUrl.split("?")[0];
                console.log("Uploaded video URL:", uploadedVideoUrl);



                /// alert('jj');

                const saveContext = bShotSaveContextOverride || bShotSaveContextRef.current;
                // S3 owns the completed bytes now. Metadata persistence only retains URLs.
                const savedIndex = resolveSceneTargetIndex(sceneTarget);
                if (saveContext.upscale && sceneSourceDataRef.current.VideoArrayCloud?.[savedIndex] !== saveContext.upscale.sourceUrl) saveContext.upscale.promote = false;
                if (saveContext.upscale?.promote !== false) {
                    adoptSavedSceneVideo(sceneTarget, uploadedVideoUrl, videoBlob, videoObjectUrl, expectedPreview, replacedBlob, isCurrentUpload, ownsHistory || isCurrentUpload);
                } else {
                    // This upscale belongs to an earlier source; retain its URL without replacing the current clip.
                    if ((ownsHistory || isCurrentUpload)() && savedIndex >= 0) {
                        videoOwnershipCallbacksRef.current.setVideoArrayBlob((previous: any[]) => releaseSavedVideoBlob(previous, savedIndex, videoBlob));
                    }
                    if (typeof videoObjectUrl === 'string' && videoObjectUrl.startsWith('blob:')) {
                        mediaPreviewRevocationsRef.current.add(videoObjectUrl); setMediaOwnershipVersion(version => version + 1);
                    }
                }
                const ownerKey = `${saveContext.storageOwner?.projectId || PostId}:${getSceneTargetKey(sceneTarget)}`;
                const completedUpscale = videoUpscaleCompletedRef.current[ownerKey];
                if (completedUpscale?.blob === videoBlob) {
                    completedUpscale.videoUrl = uploadedVideoUrl;
                    delete completedUpscale.blob;
                    delete videoUpscaleProviderResultsRef.current[ownerKey];
                }
                videoStorageOperationsRef.current.stored?.(sceneTarget, uploadedVideoUrl, saveContext, isCurrentUpload,
                    undefined, undefined, { ...(saveContext.storageOwner || { projectId: String(PostId), creationProjectId }), ownsHistory });
                return uploadedVideoUrl;

                // (Optional) Save the final URL to your database
                // e.g.: await saveToDatabase(uploadedVideoUrl, promptData, userData);
            } catch (err: any) {
                const failedSceneIndex = resolveSceneTargetIndex(sceneTarget);
                if (failedSceneIndex >= 0) {
                    setGeneratingAt(failedSceneIndex, false);
                    finishLoader(failedSceneIndex, true);
                }

                console.error("Error uploading video to S3:", err);
                /// setError(err.message || "Error uploading video to S3");
                throw err;
            }
        },
        [PostId, creationProjectId, captureSceneTarget, adoptSavedSceneVideo]
    );






    // 1) Generate S3 signed URL
    const GenerateSignedUrlForVideo = useCallback(
        async (videoBlob: Blob, i: number, videoObjectUrl: any, bShotSaveContextOverride?: BShotSaveContextSnapshot, sceneTargetOverride?: SceneTarget, ownsSourceSave?: () => boolean, ownsSourceHistory?: () => boolean) => {
            if (!videoBlob) {
                /// setError("No video blob for upload.");
                return;
            }

            const sceneTarget = sceneTargetOverride || captureSceneTarget(i);
            const requestSceneIndex = resolveSceneTargetIndex(sceneTarget);
            if (requestSceneIndex < 0) throw new Error("Video upload target scene no longer exists.");
            const ownerKey = `${PostId}:${getSceneTargetKey(sceneTarget)}`;
            const uploadClaim = Symbol("video-upload");
            if (!ownsSourceSave || ownsSourceSave()) latestVideoUploadRef.current.set(ownerKey, uploadClaim);
            const expectedPreview = sceneSourceDataRef.current.VideoArray?.[requestSceneIndex] ?? null;
            const replacedBlob = sceneSourceDataRef.current.VideoArrayBlob?.[requestSceneIndex];
            const isCurrentUpload = captureVideoUploadOwner(sceneTarget, ownerKey, uploadClaim, ownsSourceSave);
            const ownsHistory = ownsSourceHistory || ownsSourceSave || captureMediaSaveOwner(sceneTarget);
            const claims = videoUploadClaimsRef.current.get(ownerKey) || new Set<symbol>();
            claims.add(uploadClaim); videoUploadClaimsRef.current.set(ownerKey, claims);
            setVideoSavingScenes(previous => ({ ...previous, [ownerKey]: true }));

            try {
                console.log("ðŸ”¥ [2] GenerateSignedUrlForVideo Entry:", {
                    index: i,
                    currentVideoArrayCloudVal: VideoArrayCloud[i],
                    videoObjectUrl,
                    isBShotModeActive
                });

                const saveContext = { ...(bShotSaveContextOverride || bShotSaveContextRef.current),
                    previousVideoUrl: sceneSourceDataRef.current.VideoArrayCloud?.[requestSceneIndex] };
                // Example: pass any needed metadata or parameters in requestData

                const requestData = {
                    values: { count: 1 },
                };

                // Request a signed URL from your server
                const response = await axios.post<any>(
                    `${CLIK_URL}/get_signed_url_video`,
                    requestData,
                    { withCredentials: true } // If your server requires credentials/cookies
                );

                // Expect the server to respond with { signedUrl: "...", ... }

                const holder = response.data.holder;

                if (!holder || holder.length !== 1) {
                    throw new Error("Invalid signed URL response.");
                }

                const signedUrl = holder[0];


                if (!signedUrl) {
                    throw new Error("No signedUrl returned from server");
                }

                const { urlVideo } = signedUrl;

                // 2) Once we have a signed URL, PUT the video blob to S3
                const uploadedVideoUrl = await PutVideoInS3WithURL(videoBlob, urlVideo, requestSceneIndex, videoObjectUrl, saveContext, sceneTarget, isCurrentUpload, expectedPreview, replacedBlob, ownsHistory);
                if (saveContext.upscale) {
                    for (const url of [saveContext.upscale.sourceUrl, uploadedVideoUrl]) {
                        if (typeof url === 'string') retainedUpscaleUrlsRef.current.add(url.split('?')[0]);
                    }
                    ProtectSavedMediaFromDeleteLater([saveContext.upscale, uploadedVideoUrl]);
                }

                console.log("signed URL:", signedUrl);
                return uploadedVideoUrl;
            } catch (err: any) {
                const failedSceneIndex = resolveSceneTargetIndex(sceneTarget);
                if (failedSceneIndex >= 0) {
                    setGeneratingAt(failedSceneIndex, false);
                    finishLoader(failedSceneIndex, true);
                }

                console.error("Error generating video signed URL:", err);
                ///setError(err.message || "Error generating video signed URL");
                throw err;
            } finally {
                // Keep the lightweight latest token until another upload/project
                // supersedes it: deferred React state updaters still check it.
                claims.delete(uploadClaim);
                if (!claims.size) {
                    videoUploadClaimsRef.current.delete(ownerKey);
                    setVideoSavingScenes(previous => { const next = { ...previous }; delete next[ownerKey]; return next; });
                }
            }
        },
        [PostId, creationProjectId, captureSceneTarget, resolveSceneTargetIndex, captureVideoUploadOwner, PutVideoInS3WithURL]
    );



