    // The "Draw" button calls the above function
    const handleDraw = async (newValue: any, im: any, type: number, bShotSaveContextOverride?: BShotSaveContextSnapshot, sceneTargetOverride?: SceneTarget): Promise<boolean> => {
        if (!allowgetImage) return false;
        const generationTarget = sceneTargetOverride || captureSceneTarget(index);
        const generationIndex = resolveSceneTargetIndex(generationTarget);
        const promptToGenerate = cleanPromptLiterals(String(newValue || "")).trim();
        if (!promptToGenerate || generationIndex < 0) return false;

        // Loader FIRST, after the guards above and before any await.
        //
        // ensureImageIntentReady is a network round-trip, and the loader used to
        // start inside handleSubmitFluxImageNew after it — so for ~2s a click
        // produced no visible change at all and read as "it didn't work". People
        // clicked again and paid for a second generation.
        //
        // The button is deliberately NOT disabled and gets no opacity: a bad
        // generation should be abandonable, so a deliberate re-click must stay
        // instant. This only makes the first click visible.
        setGeneratingAt(generationIndex, true);
        startLoader(generationIndex);

        if (bShotSaveContextOverride?.automaticBShot && canSubmitBShotWork && !canSubmitBShotWork()) {
            setGeneratingAt(generationIndex, false); finishLoader(generationIndex, true); return false;
        }
        // Intent is a pipeline stage like Planx or the scene prompt: it must be
        // current before generation runs, and a failure stops generation and
        // raises the error pill, exactly as every other stage does.
        const intentReady = ensureImageIntentReady
            ? await ensureImageIntentReady(generationTarget, promptToGenerate, "Image generation requested")
            : true;
        if (!intentReady) {
            setGeneratingAt(generationIndex, false);
            finishLoader(generationIndex, true);
            globalErrorEmitter.emit("Intent sync is not ready. The image was not generated; retry to sync this prompt.", generationIndex);
            return false;
        }
        // In array mode, we use base[index], in single mode base[0]
        // const baseToSend = isArrayMode ? base[index] : base[0] || "";
        if (bShotSaveContextOverride?.automaticBShot && canSubmitBShotWork && !canSubmitBShotWork()) {
            setGeneratingAt(generationIndex, false); finishLoader(generationIndex, true); return false;
        }
        await handleSubmitFluxImageNew(im, promptToGenerate, Seed, type, currentSelectedPrompts, bShotSaveContextOverride, generationTarget);
        return true;
    };

    /**
     * Renders one scene's image for an arbitrary target, A-shot or B-shot.
     *
     * This is deliberately the SAME sequence the "Default" button runs — prompt
     * resolution, draft commit, loader, then handleDraw with an explicit
     * sceneTargetOverride. The backend prices and charges the generation route
     * once successful, exactly as a manual click does.
     *
     * Returns false when the slot could not be started (no prompt, unknown
     * target, generation disabled) so the caller can move on to the next one.
     */
    const generateSceneImageForTarget = useCallback(async (target: SceneTarget): Promise<boolean> => {
        if (!allowgetImage) return false;
        const targetIndex = resolveSceneTargetIndex(target);
        if (targetIndex < 0) return false;

        const scenePrompt = String(
            GeneratedTextx?.[targetIndex]
            || GeneratedText?.[targetIndex]
            || steps?.[targetIndex]
            || ""
        ).trim();
        if (!scenePrompt) return false;

        // The save context MUST be built from the target, not sampled from the
        // editor. getBShotSaveContextSnapshot() reads bShotSaveContextRef, which
        // mirrors the props describing whichever scene is currently open
        // (parentSceneIndex=activeEdit, bIndex=activeBShotEdit). Letting it
        // default would persist an auto-fired B-shot against the active scene's
        // slot — the image renders in the right place but moves or vanishes on
        // reload. Passing an explicit override is what makes off-screen B-shot
        // generation safe.
        const bShotSaveContext: BShotSaveContextSnapshot = {
            isBShotMedia: target.type === 'B',
            isBShotGridContext: target.type === 'B',
            onInstantBShotSave,
            textValue: scenePrompt,
            parentSceneIndex: target.index,
            bIndex: target.type === 'B' ? (target.bIndex ?? 0) : null,
            automaticBShot: target.type === 'B',
        };

        refreshImagePromptReferences(scenePrompt, target);
        setImagePromptDraftForTarget(target, scenePrompt, true);
        setGeneratingAt(targetIndex, true);
        startLoader(targetIndex);
        return handleDraw(scenePrompt, GeneratedImages3, 0, bShotSaveContext, target);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        allowgetImage, resolveSceneTargetIndex, GeneratedTextx, GeneratedText, steps,
        refreshImagePromptReferences, setImagePromptDraftForTarget, setGeneratingAt,
        startLoader, GeneratedImages3, onInstantBShotSave, ensureImageIntentReady,
    ]);

    // Publish the generator to the parent. EditStory stays mounted even when the
    // editor is closed, so Storybook can drive it at any time.
    useEffect(() => {
        onRegisterAutoImageGenerator?.(generateSceneImageForTarget);
        return () => onRegisterAutoImageGenerator?.(null);
    }, [onRegisterAutoImageGenerator, generateSceneImageForTarget]);



