        const activeCharacterCount = Array.isArray(activeCharsForScene) ? activeCharsForScene.length : 0;
        const referenceCount = Array.isArray(extendedReferenceImages) ? extendedReferenceImages.length : 0;
        const sceneReferenceCount = Array.isArray(validSceneImageRecords) ? validSceneImageRecords.length : 0;
